const event = $input.first().json;
const session = event.data?.object ?? event;

if (event.type && event.type !== 'checkout.session.completed') return [];
if (session.payment_status && session.payment_status !== 'paid') return [];

const recipient = session.customer_details?.email || session.customer_email;
const paymentLink = session.payment_link;
if (!recipient) throw new Error('Stripe no proporcionó el correo del cliente.');

const products = {
  'plink_1UE7lFDjPyCcLTbcJX8jy3CP': { subject: 'Tu guía Matavicios — Deja el tabaco', title: 'Deja el tabaco', downloadUrl: 'https://matavicios.com/downloads/Matavicios-Deja-el-Tabaco.pdf' },
  'plink_1UE7nZDjPyCcLTbcT3WYUe1y': { subject: 'Tu guía Matavicios — Cambiar tu relación con el cannabis', title: 'Cambiar tu relación con el cannabis', downloadUrl: 'https://matavicios.com/downloads/Matavicios-Cannabis.pdf' },
  'plink_1UE7pdDjPyCcLTbcjp4sPePZ': { subject: 'Tu guía Matavicios — Uso de pornografía que te preocupa', title: 'Uso de pornografía que te preocupa', downloadUrl: 'https://matavicios.com/downloads/Matavicios-Uso-de-Pornografia.pdf' },
  'plink_1UE7riDjPyCcLTbcFUc1EP29': { subject: 'Tu pack completo Matavicios', title: 'Pack completo', downloadUrl: 'https://matavicios.com/downloads/Matavicios-Pack-Completo.zip' }
};

const product = products[paymentLink];
if (!product) throw new Error(`Enlace de pago no reconocido: ${paymentLink || 'vacío'}`);

const html = `<div style="font-family:Arial,sans-serif;max-width:600px;margin:0 auto;color:#2c2927;line-height:1.6"><h1 style="font-size:24px;margin-bottom:16px">Gracias por tu compra</h1><p>Hola,</p><p>Tu guía <strong>${product.title}</strong> ya está lista.</p><p style="margin:28px 0"><a href="${product.downloadUrl}" style="display:inline-block;background:#6f7e67;color:#ffffff;padding:13px 20px;border-radius:6px;text-decoration:none;font-weight:700">Descargar mi guía</a></p><p>Guárdala en un lugar que encuentres fácilmente. Puedes volver a este correo cuando la necesites.</p><p>Un abrazo,<br>Matavicios</p></div>`;

return [{ json: { recipient, subject: product.subject, html, productTitle: product.title, downloadUrl: product.downloadUrl, paymentLink, sessionId: session.id } }];
